return {rwnpc01={id="rwnpc01",baseId="rwnpc01",combatid={1,1001},name="连翘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"311007",1}},{type="gaintab",args={"311011",1}},{type="doc",args={"YEL连翘：你知道今日是送穷的日子么？把一些旧物件抛弃，也是一种辞旧迎新，据说是为了接纳更多的新福气。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL连翘：我倒是没什么可以送的，所以扫了几片树叶就送了，这是不是说明其实我很富有，哼哼，就是这样的。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL连翘：不过你来之前刘大哥和他妻子气呼呼的过去，刘大哥还想让我们帮劝劝什么的，我们还是过去看看吧。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL连翘：一直听说刘大哥是有名惧内，刚刚一见果然名不虚传啊。NOR","YEL连翘：不知道他们怎么样了，日行一善，就劝劝他们吧！刚刚好像是见他们往中央大街过去了，我们也去看看吧。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL连翘：他们好像吵得很激烈，我们还是先问问刘大哥看怎么了？NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL连翘：珍贵之物？那怎么会舍得丢弃，或许婉莲姐姐有她自己的苦衷，我们还是先问问她吧。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL连翘：感觉他们都在各说各话呢，为什么不好好的聊一聊呢？NOR"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"311011",1}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"311007",1}},{type="inroom",args={"any","hdroom0518"}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"311007",2}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="eq